<script setup lang="ts">
import {joinMessages as joinStatusMessages} from '../module-localization.ts';
import {uiErrorMessage as displayErrorValue} from '../module-localization.ts';

import {tr,message as localizedMessage,messageRef} from '../../i18n/index.ts';
import {useWebSettings,settingsFields} from '../../state/web-settings.ts';
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import PdfReader from './PdfReader.vue';
import {vResizablePanels} from '../../layout/resizablePanels.ts';
import AppIcon from '../../components/AppIcon.vue';
import {citation,citationStyles,type CitationStyle} from './citations.ts';
import {copyText} from '../../platform/clipboard.ts';
import ModalDialog from '../../components/ModalDialog.vue';
import {pageScale} from '../../state/pageZoom.ts';
import {papers as desktopPapers,paperStatusWarning,papersAvailable,missing,bytesLabel,onPaperStatus,type PaperStatus,type Paper,type PaperLanguage,type LocalLibrary,type PapersClient} from '../../platform/papers.ts';
const props=defineProps<{active?:boolean;port?:PapersClient;stateKey?:string}>();const emit=defineEmits<{help:[]}>();
const papers:PapersClient=props.port??desktopPapers;const available=()=>!!props.port||papersAvailable();
const state=ref<PaperStatus>({firstLaunch:'',warning:'',papers:[]});
const local=ref<LocalLibrary>({root:'',folders:[],documents:[]}),localRevision=ref(0);
const source=ref<'server'|'local'>('server'),serverSelected=ref(''),localSelected=ref('');
const details=ref(false),citeOpen=ref(false),citeStyle=ref<CitationStyle>('GB/T 7714—2015'),copyNotice=messageRef();
const language=ref<PaperLanguage>('original'),page=ref(1),search=ref(''),period=ref(''),folder=ref('*');
const busy=ref(false),settingsBusy=ref(false),error=messageRef(),progress=messageRef(),notice=messageRef(),backgroundWarning=messageRef();
const interval=ref(6),settingsInterval=ref(6),settingsOpen=ref(false),historical=ref(false),archivePeriod=ref(''),chosen=ref<string[]>([]),showObtained=ref(false);
const folderOpen=ref(false),folderName=ref(''),moveOpen=ref(false),destinationFolder=ref(''),importOpen=ref(false);
const trashOpen=ref(false),trashItems=ref<{id:string;title:string}[]>([]);
async function openTrash(){await action(async()=>{trashItems.value=await papers.trash!();trashOpen.value=true;});}
async function restoreTrash(id:string){await action(async()=>{applyLocal(await papers.restoreLocal!(id));trashItems.value=await papers.trash!();notice.value=localizedMessage('modules.paper-reading.text.1b8e3268ec7e');});}
const deleteTarget=ref<{source:'server'|'local';folder:string}|null>(null);
const paperMenu=ref<{source:'server'|'local';id:string;title:string;notice?:boolean;x:number;y:number}|null>(null),menuElement=ref<HTMLElement>();
const deletePaperTarget=ref<{source:'server'|'local';id:string;title:string;notice?:boolean}|null>(null);
const today=ref(new Date().toLocaleDateString('sv-SE'));
const selected=computed(()=>source.value==='server'?serverSelected.value:localSelected.value);
const availableNotice=computed(()=>state.value.notice&&!state.value.notice.dismissed?state.value.notice:undefined);
const serverPapers=computed(()=>state.value.papers.filter(p=>!p.dismissed&&p.publishedAt<=today.value&&(p.downloaded||p.acquired||p.publishedAt>=state.value.firstLaunch||(p.updatedAt??'')>=state.value.firstLaunch)).sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt)||a.title.localeCompare(b.title)));
const sourceItems=computed(()=>source.value==='server'?serverPapers.value:local.value.documents);
const years=computed(()=>[...new Set(sourceItems.value.map(p=>p.publishedAt.slice(0,4)))].sort().reverse());
const months=computed(()=>[...new Set(sourceItems.value.filter(p=>!period.value||p.publishedAt.startsWith(period.value.slice(0,4))).map(p=>p.publishedAt.slice(0,7)))].sort().reverse());
const folders=computed(()=>source.value==='server'?state.value.folders??[]:local.value.folders);
const visible=computed(()=>sourceItems.value.filter(p=>(!period.value||p.publishedAt.startsWith(period.value))&&(!search.value||`${p.title} ${p.titleZh}`.toLowerCase().includes(search.value.toLowerCase()))&&(folder.value==='*'||(source.value==='local'?('folder' in p?p.folder:''):(state.value.collections?.[p.id]??''))===folder.value)));
const current=computed<Paper|undefined>(()=>{
 if(source.value==='server')return availableNotice.value?.id===serverSelected.value?availableNotice.value:serverPapers.value.find(p=>p.id===serverSelected.value);
 const p=local.value.documents.find(p=>p.id===localSelected.value);if(!p)return;
 const asset={path:'',size:p.size,sha256:''};return {...p,local:true,authors:'',version:tr('modules.paper-reading.text.76dade2029ef'),sourceUrl:'',submittedAt:p.publishedAt,license:{id:tr('modules.paper-reading.text.c0b565a10fb9'),url:''},translationNote:'',guide:'',original:asset,translation:asset,downloaded:true};
});
const archive=computed(()=>[...(state.value.notice?[state.value.notice]:[]),...state.value.papers].filter(p=>p.publishedAt<=today.value).sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt)));
const archiveYears=computed(()=>[...new Set(archive.value.map(p=>p.publishedAt.slice(0,4)))].sort().reverse());
const archiveMonths=computed(()=>[...new Set(archive.value.map(p=>p.publishedAt.slice(0,7)))].sort().reverse());
const archivePapers=computed(()=>archive.value.filter(p=>!archivePeriod.value||p.publishedAt.startsWith(archivePeriod.value)));
const pendingPapers=computed(()=>archivePapers.value.filter(p=>!p.downloaded));
const selectedPapers=computed(()=>archive.value.filter(p=>!p.downloaded&&chosen.value.includes(p.id)));
const allChecked=computed(()=>pendingPapers.value.length>0&&pendingPapers.value.every(p=>chosen.value.includes(p.id)));
const downloadBytes=computed(()=>selectedPapers.value.reduce((n,p)=>n+p.original.size+(p.notice?0:p.translation.size+(p.analysisPdf?.size??0)),0));
const citationText=computed(()=>current.value?citation(current.value,citeStyle.value,today.value):'');
const readerKey=computed(()=>{if(!current.value)return '';if(current.value.local){const document=local.value.documents.find(p=>p.id===current.value!.id);return JSON.stringify([props.stateKey??'',local.value.root,current.value.id,document?.contentVersion??'legacy-refresh:'+localRevision.value]);}return [current.value.id,current.value.original.sha256,current.value.translation.sha256,current.value.analysisPdf?.sha256??''].join(':');});
let controller:AbortController|undefined;let stopMaintenance:(()=>void)|undefined;
const positions=new Map<string,number>();const unsubscribe=(papers.onStatus??onPaperStatus)(apply);
function apply(value:PaperStatus){state.value=value;backgroundWarning.value=paperStatusWarning(value);interval.value=value.checkIntervalHours??6;if(!serverSelected.value||(!serverPapers.value.some(p=>p.id===serverSelected.value)&&availableNotice.value?.id!==serverSelected.value))serverSelected.value=availableNotice.value?.id??serverPapers.value[0]?.id??'';chosen.value=chosen.value.filter(id=>archive.value.some(p=>p.id===id&&!p.downloaded));}
function applyLocal(value:LocalLibrary){if(value.cancelled)return;localRevision.value++;local.value=value;if(value.selected)localSelected.value=value.selected;else if(value.imported?.length)localSelected.value=value.imported[0];else if(!value.documents.some(p=>p.id===localSelected.value))localSelected.value=value.documents[0]?.id??'';if(value.failures?.length)error.value=value.failures.join('\n');}
watch(selected,()=>{if(current.value?.notice||current.value?.local)language.value='original';page.value=positions.get(selected.value+':'+language.value)??1;details.value=false;});
watch(source,()=>{search.value='';period.value='';folder.value='*';language.value='original';});
function changeLanguage(value:PaperLanguage){language.value=value;page.value=positions.get(selected.value+':'+value)??1;}
function remember(value:number){page.value=value;positions.set(selected.value+':'+language.value,value);}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=displayErrorValue(e);}finally{busy.value=false;progress.value='';}}
async function getPapers(ids:string[]){await action(async()=>{controller=new AbortController();try{apply(await papers.downloadSelected(ids,controller.signal,p=>{progress.value=localizedMessage('modules.paper-reading.text.5670eee268c2',{v0:bytesLabel(p.received),v1:bytesLabel(p.total)});}));}catch(e){try{apply(await papers.status());}catch{}throw e;}});}
async function refresh(){await action(async()=>{const acquired=new Set(state.value.papers.filter(p=>p.acquired||p.downloaded).map(p=>p.id));today.value=new Date().toLocaleDateString('sv-SE');controller=new AbortController();apply(await papers.refresh(controller.signal));const ids=missing(state.value.papers,state.value.firstLaunch,today.value).map(p=>p.id);if(ids.length){apply(await papers.downloadSelected(ids,controller.signal,p=>{progress.value=localizedMessage('modules.paper-reading.text.5670eee268c2',{v0:bytesLabel(p.received),v1:bytesLabel(p.total)});}));const added=ids.filter(id=>!acquired.has(id)).length,updated=ids.length-added;notice.value=joinStatusMessages(added?localizedMessage('modules.paper-reading.text.b1192fb1f532',{v0:added}):'',added&&updated?' ':'',updated?localizedMessage('modules.paper-reading.text.292a55f9f60d',{v0:updated}):'');}else notice.value=localizedMessage('modules.paper-reading.text.536c73779d7f',{v0:state.value.papers.length});});}
async function history(){historical.value=true;archivePeriod.value=archiveYears.value[0]??'';chosen.value=[];showObtained.value=false;await action(async()=>{controller=new AbortController();apply(await papers.refresh(controller.signal));archivePeriod.value=archiveYears.value[0]??'';});}
function selectAll(){const ids=new Set(chosen.value);for(const p of pendingPapers.value){if(allChecked.value)ids.delete(p.id);else ids.add(p.id);}chosen.value=[...ids];}
async function autoCheck(event:Event){settingsBusy.value=true;error.value='';try{apply(await papers.setAutoReceive((event.target as HTMLInputElement).checked));}catch(e){error.value=displayErrorValue(e);}finally{settingsBusy.value=false;}}
async function saveInterval(){settingsBusy.value=true;error.value='';try{apply(await papers.setInterval(settingsInterval.value));notice.value=localizedMessage('modules.paper-reading.text.214c071d4494');settingsOpen.value=false;}catch(e){error.value=displayErrorValue(e);}finally{settingsBusy.value=false;}}
async function chooseRoot(){await action(async()=>{const value=await papers.chooseLibrary();if(!value.cancelled&&value.root!==local.value.root){search.value='';period.value='';folder.value='*';}applyLocal(value);});}
async function refreshLocal(){await action(async()=>applyLocal(await papers.library()));}
function prepareImport(){destinationFolder.value=folder.value==='*'?'':folder.value;importOpen.value=true;}
async function importPdfs(){await action(async()=>{const result=await papers.importLocal(destinationFolder.value);if(result.cancelled)return;applyLocal(result);importOpen.value=false;folder.value='*';period.value='';search.value='';notice.value=localizedMessage('modules.paper-reading.text.d14ffb9c43b0',{v0:result.imported?.length??0});});}
async function createFolder(){await action(async()=>{if(source.value==='local')applyLocal(await papers.createFolder(folderName.value));else apply(await papers.createRecommendationFolder(folderName.value));folderOpen.value=false;folderName.value='';});}
function prepareDelete(){if(folder.value&&folder.value!=='*')deleteTarget.value={source:source.value,folder:folder.value};error.value='';}
async function deleteFolder(){const target=deleteTarget.value;if(!target)return;await action(async()=>{if(target.source==='local'){const result=await papers.deleteFolder(target.folder);for(const [oldId,newId] of Object.entries(result.relocated??{})){const saved=positions.get(oldId+':original');if(saved!==undefined)positions.set(newId+':original',saved);if(localSelected.value===oldId){positions.set(newId+':original',page.value);localSelected.value=newId;}}applyLocal(result);folder.value=target.folder.split('/').slice(0,-1).join('/');notice.value=localizedMessage('modules.paper-reading.text.1481795cfd2a');}else{apply(await papers.deleteRecommendationFolder(target.folder));folder.value='';notice.value=localizedMessage('modules.paper-reading.text.667124f8a294');}deleteTarget.value=null;});}
function prepareMove(){destinationFolder.value=source.value==='local'?(local.value.documents.find(p=>p.id===selected.value)?.folder??''):(state.value.collections?.[selected.value]??'');moveOpen.value=true;}
async function move(){await action(async()=>{if(source.value==='local'){const old=selected.value;const result=await papers.moveLocal(old,destinationFolder.value);if(result.selected)positions.set(result.selected+':original',page.value);applyLocal(result);}else apply(await papers.collectRecommendation(selected.value,destinationFolder.value));folder.value='*';moveOpen.value=false;notice.value=source.value==='local'?localizedMessage('modules.paper-reading.text.f1d57ed4fcdc'):localizedMessage('modules.paper-reading.text.f8baa7b557e6');});}
async function copyCitation(){try{await copyText(citationText.value);copyNotice.value=localizedMessage('modules.paper-reading.text.2cf4013a9a81');}catch(e){copyNotice.value=displayErrorValue(e);}}
function openPaperMenu(event:MouseEvent,p:{id:string;titleZh:string;notice?:boolean}){if(busy.value)return;source.value==='server'?serverSelected.value=p.id:localSelected.value=p.id;const scale=pageScale.value/100;paperMenu.value={source:source.value,id:p.id,title:p.titleZh,notice:p.notice,x:Math.max(6,Math.min(event.clientX,window.innerWidth-215))/scale,y:Math.max(6,Math.min(event.clientY,window.innerHeight-55))/scale};nextTick(()=>menuElement.value?.querySelector('button')?.focus());}
function paperMenuKey(event:KeyboardEvent,p:{id:string;titleZh:string;notice?:boolean}){const r=(event.currentTarget as HTMLElement).getBoundingClientRect();openPaperMenu({clientX:r.left+25,clientY:r.bottom} as MouseEvent,p);}
function closePaperMenu(event:PointerEvent){if(!(event.target as HTMLElement)?.closest('.paper-context'))paperMenu.value=null;}
function escapePaperMenu(event:KeyboardEvent){if(event.key==='Escape')paperMenu.value=null;}
function preparePaperDelete(){if(paperMenu.value)deletePaperTarget.value={...paperMenu.value};paperMenu.value=null;error.value='';}
async function deletePaper(){const target=deletePaperTarget.value;if(!target)return;await action(async()=>{if(target.source==='server'){apply(await papers.removeDownload(target.id));serverSelected.value=availableNotice.value?.id??visible.value[0]?.id??'';notice.value=target.notice?localizedMessage('modules.paper-reading.text.40c09187910d'):localizedMessage('modules.paper-reading.text.e37f987ad546');}else{applyLocal(await papers.removeLocal(target.id));notice.value=localizedMessage('modules.paper-reading.text.b471d6a121df');}deletePaperTarget.value=null;});}
watch(()=>props.active,active=>{if(!active)paperMenu.value=null;});
onMounted(async()=>{if(!available())return;try{apply(await papers.status());try{applyLocal(await papers.library());stopMaintenance=papers.maintain?.();}catch(e){error.value=displayErrorValue(e);}}catch(e){error.value=displayErrorValue(e);}});
onMounted(()=>{document.addEventListener('pointerdown',closePaperMenu,true);document.addEventListener('keydown',escapePaperMenu);});
onBeforeUnmount(()=>{controller?.abort();stopMaintenance?.();unsubscribe();document.removeEventListener('pointerdown',closePaperMenu,true);document.removeEventListener('keydown',escapePaperMenu);});
useWebSettings(props.stateKey,{citeStyle,language,details,showObtained});
</script>
<template>
<section class="paper-reading" :aria-label="tr('modules.paper-reading.text.13e5fc715048')">
 <header class="paper-heading">
  <div class="source-tabs" role="tablist" :aria-label="tr('modules.paper-reading.text.488a68e8fb0a')"><button role="tab" :aria-selected="source==='server'" :class="{selected:source==='server'}" @click="source='server'">{{tr('modules.paper-reading.text.072c1136983a')}} <small>{{serverPapers.length}}</small></button><button role="tab" :aria-selected="source==='local'" :class="{selected:source==='local'}" @click="source='local'">{{tr('modules.paper-reading.text.09d9e6a80894')}} <small>{{local.documents.length}}</small></button></div>
  <div class="paper-actions" v-if="source==='server'"><label class="auto-switch"><input type="checkbox" :checked="state.autoReceive!==false" :disabled="settingsBusy||!available()" @change="autoCheck">{{tr('modules.paper-reading.text.556f985a69d6')}}</label><button class="interval-button" :title="state.autoReceive===false?tr('modules.paper-reading.text.b730a7fc3df7'):tr('modules.paper-reading.text.45230e5e9509',{v0:interval})" :disabled="!available()" @click="settingsInterval=interval;settingsOpen=true">{{interval}} {{tr('modules.paper-reading.text.3b6fefc50feb')}}</button><button :disabled="busy||!available()" @click="history">{{tr('modules.paper-reading.text.871fec96bb67')}}</button><button :disabled="busy||!available()" @click="refresh">{{tr('modules.paper-reading.text.184ab2d8674e')}}</button><button data-action="module-help" @click="emit('help')">{{tr('modules.paper-reading.text.a57cfcb8428d')}}</button></div>
  <div class="paper-actions" v-else><button :disabled="busy||!available()" @click="chooseRoot">{{papers.web?(local.root?tr('modules.paper-reading.text.24d26bc315b7'):tr('modules.paper-reading.text.dec361ce9626')):(local.root?tr('modules.paper-reading.text.653965a8b861'):tr('modules.paper-reading.text.c4ed4185e119'))}}</button><button :disabled="busy||!local.root" @click="refreshLocal">{{tr('modules.paper-reading.text.aee887434131')}}</button><button class="primary" :disabled="busy||!local.root" @click="prepareImport">{{tr('modules.paper-reading.text.9464159fda09')}}</button><button v-if="papers.web" :disabled="busy" @click="openTrash">{{tr('modules.paper-reading.text.ba35dc23b245')}}</button><button data-action="module-help" @click="emit('help')">{{tr('modules.paper-reading.text.a57cfcb8428d')}}</button></div>
 </header>
 <p v-if="!available()" class="paper-notice">{{tr('modules.paper-reading.text.ced67c4b673b')}}</p>
 <div v-if="busy||error||notice||backgroundWarning" class="paper-notice" role="status"><span>{{error||notice||backgroundWarning||progress||tr('modules.paper-reading.text.574ec7517de1')}}</span><button v-if="busy" @click="controller?.abort()">{{tr('modules.paper-reading.text.f8026e47df61')}}</button><button v-else @click="error='';notice='';state.warning='';backgroundWarning=''">{{tr('modules.paper-reading.text.afd4b783536b')}}</button></div>
 <div class="paper-body" v-resizable-panels="{key:'M18:library',center:'.paper-reader,.paper-empty',centerMin:440,panels:[{selector:'.paper-library',side:'left',label:tr('modules.paper-reading.text.6a44457675b8'),initial:250,min:190,max:480}]}">
  <aside class="paper-library" :aria-label="tr('modules.paper-reading.text.49550b196758')">
   <div class="library-tools"><input v-model="search" :aria-label="tr('modules.paper-reading.text.a86272842201')" type="search" :placeholder="tr('modules.paper-reading.text.c71ee6bfb32d')"><div class="library-filter"><select :aria-label="tr('modules.paper-reading.text.8c2be5a29dec')" :value="period.slice(0,4)" @change="period=($event.target as HTMLSelectElement).value"><option value="">{{tr('modules.paper-reading.text.ce68de20b706')}}</option><option v-for="year in years" :key="year" :value="year">{{tr('modules.paper-reading.year_label',{year})}}</option></select><select :aria-label="tr('modules.paper-reading.text.6339c2f6833b')" :value="period.length===7?period:''" @change="period=($event.target as HTMLSelectElement).value||period.slice(0,4)"><option value="">{{tr('modules.paper-reading.text.660f69de1a7f')}}</option><option v-for="month in months" :key="month" :value="month">{{tr('modules.paper-reading.month_label',{month:Number(month.slice(5))})}}</option></select></div><div class="library-filter"><select v-model="folder" :aria-label="tr('modules.paper-reading.text.c3aef748560d')"><option value="*">{{tr(source==='local'?'modules.paper-reading.all_files':'modules.paper-reading.all_recommendations')}}</option><option value="">{{source==='local'?tr('modules.paper-reading.text.654fd603bffc'):tr('modules.paper-reading.text.4c711a3142e2')}}</option><option v-for="f in folders" :key="f" :value="f">{{f}}</option></select><button :aria-label="tr('modules.paper-reading.text.fdf0b569d820')" :title="tr('modules.paper-reading.text.fdf0b569d820')" :disabled="busy||(source==='local'&&!local.root)||!available()" @click="folderOpen=true">＋</button><button :aria-label="tr('modules.paper-reading.text.920fe6ef0593')" :title="tr('modules.paper-reading.text.920fe6ef0593')" :disabled="busy||!folder||folder==='*'||!available()" @click="prepareDelete"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7"/></svg></button></div></div>
   <div class="library-caption"><span>{{source==='server'?tr('modules.paper-reading.text.3706d41c2039'):tr('modules.paper-reading.text.57e88a43ef2b')}}</span><small>{{tr('modules.paper-reading.paper_count',{count:visible.length})}}</small></div>
   <div class="paper-list"><button v-if="source==='server'&&availableNotice" class="paper-card paper-intro" :class="{selected:selected===availableNotice.id}" :aria-pressed="selected===availableNotice.id" @click="serverSelected=availableNotice.id;language='original'" @contextmenu.prevent="openPaperMenu($event,availableNotice)" @keydown.shift.f10.prevent="paperMenuKey($event,availableNotice)"><AppIcon class="paper-file-icon" name="info"/><span class="paper-row-title">{{availableNotice.titleZh}}</span><small>{{tr('modules.paper-reading.text.0bf18cd07b12')}}</small></button><button v-for="p in visible" :key="p.id" class="paper-card" :class="{selected:p.id===selected}" :title="`${p.titleZh}\n${p.title}`" :aria-pressed="p.id===selected" @click="source==='server'?serverSelected=p.id:localSelected=p.id" @contextmenu.prevent="openPaperMenu($event,p)" @keydown.shift.f10.prevent="paperMenuKey($event,p)"><AppIcon class="paper-file-icon" name="file"/><span class="paper-row-title">{{p.titleZh}}</span><small v-if="source==='server'&&'downloaded' in p&&!p.downloaded">↓</small></button><p v-if="!visible.length" class="hint empty-library">{{source==='local'&&!local.root?tr('modules.paper-reading.text.38382ed66a1c'):tr('modules.paper-reading.text.dc4e23b36201')}}</p></div>
   <div class="library-bottom" v-if="source==='local'"><span :title="local.root">{{local.root||tr('modules.paper-reading.text.0782786507ff')}}</span><small>{{papers.web?tr('modules.paper-reading.text.f7c809ebfedd'):tr('modules.paper-reading.text.d9d96be74b03')}}</small></div><div class="library-bottom" v-else><span>{{state.autoReceive===false?tr('modules.paper-reading.text.7434d47406bd'):tr('modules.paper-reading.text.429790910442',{v0:interval})}}</span><small>{{tr('modules.paper-reading.text.ba22b4139b46')}} {{state.firstLaunch||tr('modules.paper-reading.text.7250d23de93f')}} {{tr('modules.paper-reading.text.802c73b92598')}}</small></div>
  </aside>
